// Génère toutes les combinaisons secteur × ville × query
const settings = {
  villes: [
    'Paris', 'Lyon', 'Marseille', 'Bordeaux', 'Nantes',
    'Toulouse', 'Lille', 'Strasbourg', 'Grenoble', 'Nice',
    'Montpellier', 'Rennes', 'Bruxelles', 'Genève', 'Lausanne'
  ],
  secteurs: [
    { id: 'restauration',  label: 'Restauration', queries: ['restaurant', 'brasserie', 'pizzeria'], score_min_avis: 200 },
    { id: 'beaute',        label: 'Beauté',        queries: ['salon coiffure', 'institut beauté', 'esthéticienne'], score_min_avis: 100 },
    { id: 'automobile',   label: 'Automobile',    queries: ['garage automobile', 'carrosserie'], score_min_avis: 150 },
    { id: 'auto_ecole',   label: 'Auto-école',    queries: ['auto-école', 'école conduite'], score_min_avis: 100 },
    { id: 'sante',        label: 'Santé',          queries: ['médecin', 'dentiste', 'kinésithérapeute'], score_min_avis: 80 },
    { id: 'artisanat',    label: 'Artisanat',      queries: ['plombier', 'électricien'], score_min_avis: 80 },
    { id: 'hotellerie',   label: 'Hôtellerie',     queries: ['hôtel', 'auberge'], score_min_avis: 100 },
    { id: 'services',     label: 'Services',       queries: ['agence immobilière', 'comptable'], score_min_avis: 50 },
    { id: 'sport',        label: 'Sport & Loisirs', queries: ['salle de sport', 'yoga', 'coach sportif'], score_min_avis: 80 },
    { id: 'commerce',     label: 'Commerce',       queries: ['boulangerie', 'fleuriste', 'pharmacie'], score_min_avis: 100 }
  ]
};

const combinations = [];
for (const secteur of settings.secteurs) {
  for (const ville of settings.villes) {
    for (const query of secteur.queries) {
      combinations.push({
        json: {
          secteur_id:    secteur.id,
          secteur_label: secteur.label,
          score_min_avis: secteur.score_min_avis,
          ville:         ville,
          query:         `${query} ${ville} France`,
          batch_key:     `${secteur.id}_${ville}_${query}`.replace(/\s+/g, '_')
        }
      });
    }
  }
}
return combinations;

// Extraire et filtrer les résultats pertinents
const input = $input.first().json;
const context = $('Traiter une combinaison à la fois').first().json;

if (!input.results || input.results.length === 0) {
  return [];
}

return input.results
  .filter(place => {
    const hasEnoughReviews = (place.user_ratings_total || 0) >= context.score_min_avis;
    const hasRating = place.rating !== undefined;
    return hasEnoughReviews && hasRating;
  })
  .map(place => ({
    json: {
      place_id:      place.place_id,
      nom:           place.name,
      adresse:       place.formatted_address,
      note_google:   place.rating,
      nb_avis:       place.user_ratings_total || 0,
      secteur_id:    context.secteur_id,
      secteur_label: context.secteur_label,
      ville:         context.ville,
      types:         (place.types || []).join(',')
    }
  }));

// Fusionner les détails et calculer le score de potentiel
const details = $input.first().json.result || {};
const prospect = $('Extraire établissements valides').first().json;

const telephone = details.formatted_phone_number || '';
const site_web   = details.website || '';

// Calcul score (0-100)
const nb_avis     = prospect.nb_avis || 0;
const note        = prospect.note_google || 3;

// Les avis sans réponse ne sont pas disponibles via Places API — estimation
// On suppose 70% sans réponse par défaut, à affiner manuellement
const pct_sans_reponse_estime = 70;
const avis_sans_reponse_estime = Math.round(nb_avis * pct_sans_reponse_estime / 100);

// Score : fort nb avis + faible note + pct sans réponse élevé = fort potentiel
const score_avis    = Math.min(nb_avis / 500 * 100, 100) * 0.3;
const score_note    = (5 - note) / 5 * 100 * 0.2;
const score_reponse = pct_sans_reponse_estime * 0.5;
const score_total   = Math.round(score_avis + score_note + score_reponse);

// Générer un ID unique
const id = `${prospect.secteur_id}_${prospect.place_id}`.substring(0, 40);

return [{ json: {
  id,
  nom:                    prospect.nom,
  adresse:                prospect.adresse,
  secteur:                prospect.secteur_label,
  ville:                  prospect.ville,
  telephone:              telephone,
  site_web:               site_web,
  note_google:            prospect.note_google,
  nb_avis:                nb_avis,
  avis_sans_reponse:      avis_sans_reponse_estime,
  pct_sans_reponse:       pct_sans_reponse_estime,
  score:                  score_total,
  a_un_site:              site_web.length > 0,
  place_id:               prospect.place_id
}}];

// Extraire email depuis le HTML du site
const html = $input.first().json.data || '';
const prospect = $('Enrichir et scorer le prospect').first().json;

const emailRegex = /[a-zA-Z0-9._%+\-àâäéèêëîïôùûü]+@[a-zA-Z0-9.\-]+\.[a-zA-Z]{2,}/gi;
const emails = (html.match(emailRegex) || [])
  .map(e => e.toLowerCase())
  .filter(e =>
    !e.includes('example') &&
    !e.includes('noreply') &&
    !e.includes('no-reply') &&
    !e.includes('donotreply') &&
    !e.includes('webmaster') &&
    !e.includes('@sentry') &&
    !e.includes('@wp') &&
    !e.includes('wpcf7') &&
    !e.includes('@schemas') &&
    !e.endsWith('.png') &&
    !e.endsWith('.jpg')
  );

const emailUnique = [...new Set(emails)];
const email_principal = emailUnique[0] || null;

return [{ json: { ...prospect, email: email_principal, tous_emails: emailUnique.join(';') } }];

// Pas de site web — email null
const prospect = $input.first().json;
return [{ json: { ...prospect, email: null, tous_emails: '' } }];
